x.append(R(6470032,"किफ़ायती वेजी बर्गर आम की स्लॉ के साथ","इस शाकाहारी व्यंजन को कटे हुए टमाटर और ताज़ा मोत्ज़ारेला सलाद के साथ परोसें।","6","1 बर्गर + 1/4 कप स्लॉ",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 (15 औंस) कैन कैनेलिनी बीन्स (धोई और निथारी हुई)","1/2 कप प्याज (छोटे टुकड़ों में कटा हुआ)","1 कली लहसुन (बारीक कटी हुई)","1 कप सफ़ेद (बटन) मशरूम (छोटे टुकड़ों में कटे हुए)","1 कप कद्दूकस की हुई गाजर","1 बड़ा चम्मच वॉरसेस्टरशायर सॉस","1 बड़ा चम्मच कम सोडियम वाली सोया सॉस","1 कप क्विक कुकिंग ओट्स","2 छोटे चम्मच स्टेक सीज़निंग","1 मध्यम कच्चा आम (छिला, बीज निकाला और कद्दूकस किया हुआ)","1 (9 औंस) बैग पैकेट वाला कोलस्लॉ मिक्स","2 बड़े चम्मच राइस वाइन विनेगर","1 बड़ा चम्मच ऑलिव ऑयल","6 पत्ते लेट्यूस (बड़े)"],
["एक बड़े नॉन-स्टिक सॉते पैन पर कुकिंग स्प्रे लगाएँ। एक तरफ रख दें।","कैनेलिनी बीन्स, प्याज, लहसुन, मशरूम, गाजर, वॉरसेस्टरशायर सॉस, सोया सॉस, ओटमील, मॉन्ट्रियल स्टेक सीज़निंग और नमक (वैकल्पिक) को फ़ूड प्रोसेसर में मिलाएँ। कई बार पल्स करें जब तक मिश्रण मिल न जाए लेकिन पेस्ट न बने।","बर्गर के मिश्रण को 6 बराबर हिस्सों में बाँटें और पैटी का आकार दें।","तैयार सॉते पैन को मध्यम-तेज़ आंच पर गरम करें। बर्गर को हर तरफ 6-8 मिनट सेकें। एक तरफ रख दें।","एक बड़े कटोरे में कद्दूकस किया आम, कोलस्लॉ मिक्स, राइस वाइन विनेगर और ऑलिव ऑयल मिलाएँ। लपेटने के लिए मिलाएँ।","एक बर्गर को लेट्यूस के पत्ते पर रखें और ऊपर से 3/4 कप कोलस्लॉ का मिश्रण डालें।"]))
x.append(R(6470482,"अनानास और मैंडरिन संतरे की सालसा के साथ चिकन","कुकबुक लेखिका रॉबिन वेब कहती हैं, \"जब मैं बच्चा थी, तो मुझे असल में ताज़े फल बहुत पसंद नहीं थे। लेकिन डिब्बाबंद मैंडरिन संतरे मुझे हमेशा उत्साहित करते थे और मुझे एक छोटे कट-ग्लास के कटोरे की गरम यादें हैं जिसमें मेरी माँ संतरे की छोटी-छोटी फाँकें परोसती थीं। बेशक मैंने अपने फलों की सूची बढ़ा ली है, लेकिन अब भी मानती हूँ कि मैंडरिन संतरे एक बेहतरीन बहुमुखी फल हैं। यहाँ, उष्णकटिबंधीय नारियल के साथ तीखी की गई एक सरल सालसा जीरे के स्वाद वाले सिके हुए चिकन ब्रेस्ट के साथ बहुत अच्छी लगती है।\"","4","1 ब्रेस्ट + 1/2 कप सालसा",
["1 कप डिब्बाबंद अनानास (बिना अतिरिक्त चीनी के, अच्छी तरह निथारा हुआ)","1 कप पानी या रस में पैक किए मैंडरिन संतरे (अच्छी तरह निथारे हुए, मोटे कटे हुए)","2 डंठल हरा प्याज (स्प्रिंग अनियन) (केवल सफ़ेद भाग, बारीक कटा हुआ)","1/4 कप लाल शिमला मिर्च (बारीक कटी हुई)","1 1/2 बड़े चम्मच बिना मीठे नारियल के फ्लेक्स","1/4 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स","1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच चिली पाउडर","1/4 छोटा चम्मच कोशर नमक","1/8 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच वनस्पति तेल"],
["बेकिंग शीट पर फ़ॉइल बिछाएँ। ओवन को पहले से 375 डिग्री F पर गरम करें। सालसा की सारी सामग्री एक कटोरे में मिलाएँ। ढककर 1 घंटे के लिए रेफ्रिजरेटर में रखें।","इस बीच, चिकन ब्रेस्ट से अतिरिक्त चर्बी हटा दें। जीरा, चिली पाउडर, नमक और काली मिर्च मिलाएँ। चिकन के हर टुकड़े पर मसाले का रब लगाएँ।","एक बड़ी कड़ाही में मध्यम-तेज़ आंच पर तेल गरम करें। चिकन डालें और दोनों तरफ़ कुल 10 मिनट सेकें। चिकन को तैयार बेकिंग शीट पर रखें। फ़ॉइल या बेकिंग पेपर से हल्के से ढक दें। चिकन ब्रेस्ट को पूरी तरह पकने तक, लगभग 6–7 मिनट और पकाएँ।","सालसा को कमरे के तापमान पर आने दें। पके हुए चिकन को सालसा के साथ परोसें।"]))
x.append(R(6471870,"टोफू, मशरूम और बोक चॉय रेमेन","रेमेन पसंद है? यह हल्का, शाकाहारी विकल्प आज़माएँ! अगर आपको तीखा रेमेन पसंद है तो थोड़ी सी श्रीराचा डालें।","4","2 कप",
["4 औंस सूखे रेमेन नूडल्स","1 बड़ा चम्मच तिल का तेल","1 मध्यम पीला प्याज (पतला कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","3 कप कम सोडियम वेजिटेबल ब्रॉथ","2 कप पानी","1 कप शिटाके मशरूम (कटे हुए)","1 कप ब्रोकली (फूल)","4 डंठल बेबी बोक चॉय (कटे हुए)","5 औंस गाजर (कद्दूकस की हुई)","14 औंस एक्स्ट्रा फ़र्म टोफू (पानी निथारा हुआ, दबाया हुआ और टुकड़ों में कटा हुआ)","1 1/2 बड़े चम्मच कोकोनट एमिनोज़","1 बड़ा चम्मच राइस विनेगर","2 डंठल स्प्रिंग अनियन (कटे हुए)"],
["पैकेट पर दिए निर्देशों के अनुसार रेमेन नूडल्स पकाएँ। निथारकर एक तरफ रख दें।","एक बड़े बर्तन में मध्यम आंच पर तिल का तेल गरम करें। कटा प्याज, बारीक कटा लहसुन और कद्दूकस किया अदरक डालें। प्याज के पारदर्शी होने तक भूनें।","वेजिटेबल ब्रॉथ और पानी डालें और उबाल आने तक पकाएँ (हल्की आंच पर)।","कटे हुए मशरूम, ब्रोकली के फूल, कटा बोक चॉय, कद्दूकस की हुई गाजर और टुकड़ों में कटा टोफू बर्तन में डालें। सब्ज़ियों के नरम होने तक लगभग 5–7 मिनट हल्की आंच पर पकाएँ।","कोकोनट एमिनोज़ और राइस विनेगर मिलाएँ।","पके हुए रेमेन नूडल्स को सर्विंग बाउल में बाँट दें। नूडल्स पर सब्ज़ियों से भरपूर ब्रॉथ डालें और हरे प्याज से सजाएँ।"]))
x.append(R(6472756,"रिट्ज़ के साथ जमैकन स्टफ्ड फ़िश","यह रेसिपी परिवार की पसंदीदा है। पूरी मछली, आमतौर पर येलोटेल स्नैपर या पैरटफ़िश, साबुत भरी जाती है, केले के पत्ते की पट्टियों से बाँधी जाती है, और बड़ी डंडियों पर रखकर खुली आग पर पकाई जाती है।","4","1/2 ट्राउट (लगभग 5 औंस)",
["2 छोटी या 4 फ़िलेट (त्वचा सहित) साबुत ट्राउट (या स्नैपर लें, साफ़ की हुई, शल्क हटाई हुई और क्रिसक्रॉस पैटर्न में चीरे लगी हुई)","2 स्प्रे, 0.5 ग्राम नॉनस्टिक एक्स्ट्रा वर्जिन ऑलिव ऑयल स्प्रे","1 लाइम का रस (1 लाइम से)","1 चुटकी कोशर नमक (स्वादानुसार)","1/2 कप होल-व्हीट क्रैकर्स (कुचले हुए)","1/2 कप होल व्हीट Ritz® क्रैकर्स (कुचले हुए)","1 छोटा चम्मच ताज़ा थाइम (बारीक कटा हुआ)","1 साबुत तीखी मिर्च (बीज निकाली और बारीक कटी हुई, जैसे स्कॉच बोनेट, सेरानो या जलापेनो)","1 गुच्छा (~5 डंठल) हरा प्याज (स्प्रिंग अनियन) (कटा हुआ)","1 बड़ा चम्मच मार्जरीन (बटर जैसा स्प्रेड, पिघला हुआ)"],
["तेज़ चाकू से मछली की त्वचा पर चीरे लगाएँ। मछली की चीरी हुई सतह पर कुकिंग स्प्रे करें। त्वचा पर लाइम निचोड़ें और नमक छिड़कें। सतह पर रगड़ें।","एक मध्यम कटोरे में कुचले हुए क्रैकर्स, थाइम, तीखी मिर्च, स्प्रिंग अनियन और पिघला मक्खन मिलाकर भराई तैयार करें। मछली के पेट की गुहा में भराई भरें, और टूथपिक या धातु की सींख से सींख को बुनते हुए खुला भाग बंद करें। सुरक्षित करने के लिए आप मछली की निचली तरफ़ 2 इंच के अंतराल पर टूथपिक भी लगा सकते हैं।","ग्रिल को मध्यम-तेज़ आंच पर पहले से गरम करें और ग्रिल की जाली पर रखें। बीच-बीच में पलटते हुए 15–18 मिनट तक, जब तक अंदर तक पक न जाए और बाहर से कुरकुरी परत न बन जाए, पकाएँ।"]))
x.append(R(6473360,"स्लो कुकर ग्लूटेन-मुक्त पालक लज़ान्या","यह रेसिपी झटपट बनने वाली, स्वादिष्ट और सुविधाजनक भोजन है जिसका पूरा परिवार आनंद लेगा। इसे ज़रूर आज़माएँ!","12","1 टुकड़ा (रेसिपी का 1/12)",
["9 साबुत लज़ान्या नूडल्स (ग्लूटेन-मुक्त)","24 1/2 औंस जार वाली पास्ता टमाटर सॉस (कम सोडियम वाली)","1 पैकेट फ्रोज़न पालक (10 औंस, कटा हुआ, पिघलाया और निथारा हुआ)","1 कप पार्ट-स्किम मोत्ज़ारेला चीज़ (कद्दूकस किया हुआ, बाँटकर उपयोग के लिए)","1 कप कम वसा वाला रिकोटा चीज़","1 साबुत नॉनस्टिक कुकिंग स्प्रे","1/4 कप परमेसन चीज़ (ताज़ा कद्दूकस किया हुआ)","8 औंस टमाटर सॉस (1 8 औंस का कैन, बिना नमक मिलाया हुआ)"],
["स्लो कुकर पर कुकिंग स्प्रे करें।","एक मध्यम कटोरे में रिकोटा चीज़, परमेसन चीज़, 1/4 कप मोत्ज़ारेला चीज़ और पालक मिलाएँ।","स्लो कुकर की तली में 1 कप पास्ता सॉस फैलाएँ। सॉस के ऊपर 3 नूडल्स पास-पास रखें, ज़रूरत हो तो नूडल्स को तोड़कर फ़िट करें।","नूडल्स के ऊपर लगभग 1/3 कप रिकोटा-पालक का मिश्रण फैलाएँ। पास्ता सॉस, नूडल्स और रिकोटा-पालक मिश्रण की परतें 2 बार और दोहराएँ। ऊपर से बची हुई पास्ता सॉस और कैन वाली टमाटर सॉस डालें। ऊपर से 1 कप मोत्ज़ारेला चीज़ छिड़कें।","स्लो कुकर पर ढक्कन लगाएँ। धीमी सेटिंग पर 2–3 घंटे या पकने तक पकाएँ (पकाने का समय स्लो कुकर के अनुसार अलग हो सकता है)।","* इस रेसिपी का परीक्षण ग्लूटेन-मुक्त लज़ान्या नूडल्स के साथ किया गया था, लेकिन होल-व्हीट लज़ान्या नूडल्स का उपयोग भी किया जा सकता है।"]))
x.append(R(6474350,"कटे हुए बादाम","कटे हुए बादाम की पोषण संबंधी जानकारी","1","1/2 औंस",["1/2 औंस कटे हुए बादाम"],[]))
x.append(R(6475348,"सिसिलियन जैतून सलाद","कुचले हुए जैतूनों का यह मिश्रण परिवार की पसंदीदा रेसिपी है जो कैलाब्रिया और सिसिली दोनों जगह लोकप्रिय है। सिसिली के कास्तेलवेत्रानो जैतून अब बड़े सुपरमार्केट में आसानी से मिलने लगे हैं, और अगर आपको वे उपलब्ध हैं, तो वे इस सलाद के लिए बेहतरीन विकल्प हैं। कई इटैलियन-अमेरिकी डेली \"सिसिलियन कोलोसल\" जैतून बेचते हैं, जो भी अच्छी तरह चलते हैं। आप सर्दियों में इस मिश्रण के कुछ बड़े चम्मच गरम पास्ता में, या गरम मौसम में ठंडे चावल या क्विनोआ में मिला सकते हैं। साधारण सब्ज़ियों, सीफ़ूड और मांस को सजाने का भी यह बढ़िया तरीका है।\n\nयह रेसिपी द मेडिटेरेनियन डायबिटीज़ कुकबुक से ली गई है।","16","2 बड़े चम्मच",
["1/2 पाउंड बड़े हरे जैतून (अच्छी तरह धोए, निथारे और रगड़कर सुखाए हुए)","5 डंठल अजवाइन (छोटे टुकड़ों में कटे हुए)","2 मध्यम गाजर (छिली और छोटे टुकड़ों में कटी हुई)","1 छोटा लाल प्याज (छोटे टुकड़ों में कटा हुआ)","3 कली लहसुन","2 छोटे चम्मच सूखा ओरेगैनो","1/2 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स","1/4 कप एक्स्ट्रा-वर्जिन ऑलिव ऑयल"],
["जैतूनों को कटिंग बोर्ड पर रखें। साफ़ किचन तौलिये से ढकें और मीट हैमर या कड़ाही के पिछले हिस्से से हल्के से कुचलें। (उद्देश्य जैतूनों को थोड़ा सा कुचलना है।)","जैतूनों को एक कटोरे में रखें और बची हुई सामग्री के साथ मिलाएँ।","सलाद को कमरे के तापमान पर एक घंटे के लिए मैरिनेट करें, या ढककर रेफ्रिजरेटर में कम से कम 1 दिन और अधिकतम 3 दिन तक ठंडा करें। परोसने से पहले सलाद को कमरे के तापमान पर आने दें।"]))
x.append(R(6475917,"योगर्ट रैंच ड्रेसिंग","घर की बनी चीज़ से बेहतर कुछ नहीं, रैंच ड्रेसिंग भी! मलाईदार योगर्ट प्रोटीन जोड़ता है, लेकिन इस मधुमेह के अनुकूल सलाद ड्रेसिंग में ताज़ी जड़ी-बूटियाँ ही असली सितारा हैं।","8","2 बड़े चम्मच",
["1 कप सादा नॉनफैट ग्रीक योगर्ट","2 बड़े चम्मच ताज़ा चाइव्स (बारीक कटे हुए)","2 बड़े चम्मच ताज़ा अजमोद (बारीक कटा हुआ)","1 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच प्याज पाउडर","1 छोटा चम्मच सूखी सोया (डिल)","1 छोटा चम्मच डिजॉन सरसों","1 बड़ा चम्मच एप्पल साइडर विनेगर","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["एक मध्यम आकार के कटोरे में ग्रीक योगर्ट, चाइव्स, अजमोद, लहसुन, प्याज पाउडर, सूखी डिल, डिजॉन सरसों, एप्पल साइडर विनेगर, नमक और काली मिर्च मिलाएँ।","स्वादों को आपस में घुलने देने के लिए ड्रेसिंग को रेफ्रिजरेटर में कम से कम 10 मिनट रखा रहने दें।"]))
